import Link from "next/link";import { seedFestivals } from "@/lib/festivals";import { isPast,paginate } from "@/lib/utils";import { FestivalCard } from "@/components/festival-card";export default async function Page({searchParams}:{searchParams:Promise<{page?:string}>}){const {page}=await searchParams;const all=seedFestivals.filter(x=>isPast(x));const p=paginate(all,Number(page)||1);return <main className="wrap section"><Link href="/" className="muted">← Back to upcoming festivals</Link><h1>Past Festivals Archive</h1><p className="muted">{all.length} past festivals in our database.</p><div className="grid">{p.items.map(x=><FestivalCard key={x.id} festival={x} ended/>)}</div></main>}
